option.value:
@layer reset, tokens, app, temp;

@layer reset {
    :root {
        --modern-bg-1: #060818;
        --modern-bg-2: #111a3c;
        --modern-bg-3: #132d4d;
        --modern-accent-1: #7c3aed;
        --modern-accent-2: #06b6d4;
        --modern-accent-3: #22c55e;
        --modern-danger: #ef4444;
        --modern-warning: #f59e0b;
        --modern-radius-xl: 24px;
        --modern-radius-lg: 16px;
        --modern-radius-md: 12px;
        --modern-shadow: 0 12px 35px rgba(2, 6, 23, 0.45);
        --modern-shadow-soft: 0 8px 24px rgba(15, 23, 42, 0.22);
    }

    body.kt-modern-ui {
        position: relative;
        background:
            radial-gradient(1000px 500px at 8% -5%, rgba(124, 58, 237, 0.35), transparent 60%),
            radial-gradient(900px 440px at 92% 5%, rgba(6, 182, 212, 0.28), transparent 58%),
            linear-gradient(145deg, var(--modern-bg-1), var(--modern-bg-2) 44%, var(--modern-bg-3));
        background-attachment: fixed;
    }

    body.kt-modern-ui.light-mode {
        --modern-bg-1: #eef4ff;
        --modern-bg-2: #dbeafe;
        --modern-bg-3: #f8fafc;
        --modern-shadow: 0 12px 30px rgba(30, 41, 59, 0.16);
        --modern-shadow-soft: 0 8px 22px rgba(15, 23, 42, 0.12);
    }

    @media (prefers-reduced-motion: reduce) {
        * {
            animation-duration: 0.001ms !important;
            animation-iteration-count: 1 !important;
            transition-duration: 0.001ms !important;
        }
    }
}

@layer tokens {
    body.kt-modern-ui {
        --card-bg: color-mix(in oklab, var(--surface) 74%, transparent);
        --card-border: color-mix(in oklab, var(--text-primary) 16%, transparent);
        --card-hover-border: color-mix(in oklab, var(--modern-accent-2) 38%, var(--text-primary) 10%);
    }

    @supports not (color: color-mix(in oklab, red, blue)) {
        body.kt-modern-ui {
            --card-bg: rgba(15, 23, 42, 0.72);
            --card-border: rgba(148, 163, 184, 0.32);
            --card-hover-border: rgba(6, 182, 212, 0.48);
        }

        body.kt-modern-ui.light-mode {
            --card-bg: rgba(255, 255, 255, 0.88);
            --card-border: rgba(15, 23, 42, 0.18);
            --card-hover-border: rgba(14, 165, 233, 0.42);
        }
    }
}

@layer app {
    body.kt-modern-ui .skip-link {
        position: fixed;
        left: 14px;
        top: 10px;
        z-index: 10001;
        transform: translateY(-180%);
        padding: 0.55rem 0.8rem;
        border-radius: 10px;
        border: 1px solid var(--card-border);
        background: rgba(2, 6, 23, 0.94);
        color: #f8fafc;
        text-decoration: none;
        font-weight: 700;
        transition: transform 0.2s ease;
    }

    body.kt-modern-ui .skip-link:focus-visible {
        transform: translateY(0);
    }

    body.kt-modern-ui :is(header, footer, .settings-section, .inf-center-circle, .side-main-wheel, .temp-wheel-content, .auth-logo-inner, .dashboard-container, .card-box, .stat-card, .action-card) {
        border: 1px solid var(--card-border) !important;
        background: var(--card-bg) !important;
        backdrop-filter: blur(20px) saturate(160%);
        -webkit-backdrop-filter: blur(20px) saturate(160%);
        box-shadow: var(--modern-shadow-soft);
    }

    body.kt-modern-ui header {
        border-radius: 0 0 var(--modern-radius-lg) var(--modern-radius-lg);
        margin: 0.35rem auto 0;
        width: min(1200px, 94%);
        position: sticky;
        top: max(0.2rem, env(safe-area-inset-top));
    }

    body.kt-modern-ui footer {
        width: min(1200px, 92%);
        margin: 1rem auto 1.25rem;
        border-radius: var(--modern-radius-md);
    }

    body.kt-modern-ui .nav-btn,
    body.kt-modern-ui .nav-link {
        border-radius: 999px !important;
        border-color: var(--card-border) !important;
        background: linear-gradient(135deg, rgba(124, 58, 237, 0.18), rgba(6, 182, 212, 0.18)) !important;
        color: var(--text-primary) !important;
        box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.04);
    }

    body.kt-modern-ui .brand-text h1 {
        background: linear-gradient(120deg, #ffffff 0%, #67e8f9 45%, #c4b5fd 100%) !important;
        -webkit-background-clip: text;
        -webkit-text-fill-color: transparent;
    }

    body.kt-modern-ui.light-mode .brand-text h1 {
        background: linear-gradient(120deg, #0f172a 0%, #0369a1 45%, #6d28d9 100%) !important;
        -webkit-background-clip: text;
        -webkit-text-fill-color: transparent;
    }

    body.kt-modern-ui #app-content main,
    body.kt-modern-ui main.infographic-wrapper,
    body.kt-modern-ui main {
        width: min(1240px, 96%);
        margin: 0.7rem auto 0;
        border-radius: var(--modern-radius-xl);
        padding: clamp(1rem, 2vw, 1.6rem) !important;
        background: linear-gradient(150deg, rgba(15, 23, 42, 0.48), rgba(15, 23, 42, 0.22));
        border: 1px solid var(--card-border);
    }

    body.kt-modern-ui.light-mode #app-content main,
    body.kt-modern-ui.light-mode main.infographic-wrapper,
    body.kt-modern-ui.light-mode main {
        background: linear-gradient(145deg, rgba(255, 255, 255, 0.72), rgba(241, 245, 249, 0.66));
    }

    body.kt-modern-ui .inf-center-circle,
    body.kt-modern-ui .side-main-wheel,
    body.kt-modern-ui .temp-wheel-content {
        border-radius: 28px !important;
        box-shadow: var(--modern-shadow);
    }

    body.kt-modern-ui .inf-node,
    body.kt-modern-ui .side-node-row,
    body.kt-modern-ui .temp-icon-node,
    body.kt-modern-ui .settings-section,
    body.kt-modern-ui .setting-item,
    body.kt-modern-ui .action-card,
    body.kt-modern-ui .stat-card,
    body.kt-modern-ui .card-box,
    body.kt-modern-ui .notice-card,
    body.kt-modern-ui .pin-dot {
        transition: transform 0.22s ease, box-shadow 0.22s ease, border-color 0.22s ease;
    }

    body.kt-modern-ui .inf-node,
    body.kt-modern-ui .side-node-row,
    body.kt-modern-ui .temp-icon-node,
    body.kt-modern-ui .action-card,
    body.kt-modern-ui .stat-card {
        border: 1px solid var(--card-border) !important;
        border-radius: var(--modern-radius-lg) !important;
        background: linear-gradient(160deg, rgba(124, 58, 237, 0.14), rgba(6, 182, 212, 0.08)) !important;
    }

    body.kt-modern-ui .inf-node:hover,
    body.kt-modern-ui .side-node-row:hover,
    body.kt-modern-ui .temp-icon-node:hover,
    body.kt-modern-ui .action-card:hover,
    body.kt-modern-ui .stat-card:hover,
    body.kt-modern-ui .settings-section:hover {
        transform: translateY(-2px) scale(1.01);
        border-color: var(--card-hover-border) !important;
        box-shadow: 0 12px 30px rgba(6, 182, 212, 0.2);
    }

    body.kt-modern-ui .pin-dot.filled {
        border-color: var(--modern-accent-2) !important;
        box-shadow: 0 0 0 5px rgba(6, 182, 212, 0.2), 0 0 18px rgba(6, 182, 212, 0.6) !important;
    }

    body.kt-modern-ui .pin-dot.error {
        border-color: var(--modern-danger) !important;
    }

    body.kt-modern-ui .settings-section {
        border-radius: var(--modern-radius-lg) !important;
    }

    body.kt-modern-ui .setting-item {
        border-bottom-color: color-mix(in oklab, var(--text-primary) 12%, transparent) !important;
    }

    body.kt-modern-ui .toggle-switch .slider {
        border: 1px solid var(--card-border);
        background: rgba(148, 163, 184, 0.32);
    }

    body.kt-modern-ui .toggle-switch input:checked + .slider {
        background: linear-gradient(120deg, var(--modern-accent-1), var(--modern-accent-2));
    }

    body.kt-modern-ui #change-pin-btn,
    body.kt-modern-ui #save-pin-btn,
    body.kt-modern-ui #clear-data-btn {
        border: 1px solid transparent;
        background: linear-gradient(120deg, var(--modern-accent-1), var(--modern-accent-2));
        box-shadow: 0 8px 18px rgba(6, 182, 212, 0.24);
    }

    body.kt-modern-ui #loader .spinner {
        border-right-color: var(--modern-accent-2) !important;
        border-top-color: var(--modern-accent-1) !important;
    }

    @container (min-width: 900px) {
        body.kt-modern-ui .infographic-container {
            gap: clamp(16px, 2vw, 38px);
        }
    }
}

@layer temp {
    body.kt-modern-ui .dashboard-container {
        border-radius: 28px;
        overflow: clip;
        min-height: min(780px, 95dvh);
    }

    body.kt-modern-ui .sidebar {
        background: linear-gradient(170deg, rgba(12, 74, 110, 0.94), rgba(88, 28, 135, 0.94));
        border-top-right-radius: 28px;
    }

    body.kt-modern-ui .nav-item.active {
        border-radius: 999px 0 0 999px;
        margin-left: 14px;
        box-shadow: 0 8px 20px rgba(15, 23, 42, 0.2);
    }

    body.kt-modern-ui .main-content {
        background: transparent;
        gap: 16px;
    }

    body.kt-modern-ui .logo {
        letter-spacing: 0.04em;
        text-transform: uppercase;
    }

    body.kt-modern-ui .calendar-days .day-cell,
    body.kt-modern-ui .calendar-months span {
        border-radius: 10px;
    }
}

@layer app {
    body.kt-modern-ui {
        --control-size: 42px;
        --control-radius: 999px;
        --focus-ring: 0 0 0 3px rgba(6, 182, 212, 0.34);
    }

    body.kt-modern-ui :is(.nav-btn, .nav-link) {
        width: var(--control-size) !important;
        height: var(--control-size) !important;
        border-radius: var(--control-radius) !important;
    }

    body.kt-modern-ui :is(button, [role='button'], a, input, select, textarea):focus-visible {
        outline: none;
        box-shadow: var(--focus-ring) !important;
    }

    body.kt-modern-ui :is(.inf-node, .side-node-row, .temp-icon-node, .action-card, .stat-card, .card-box, .notice-card).kt-press {
        transform: scale(0.98) !important;
    }

    body.kt-modern-ui.kt-page-enter {
        opacity: 0.001;
        transform: translateY(8px);
    }

    body.kt-modern-ui.kt-page-enter.kt-page-enter-active {
        opacity: 1;
        transform: translateY(0);
        transition: opacity 260ms ease, transform 260ms ease;
    }

    body.kt-modern-ui #loader {
        position: fixed;
        inset: 0;
        z-index: 9999;
        display: grid;
        place-items: center;
        background: rgba(2, 6, 23, 0.42);
        backdrop-filter: blur(4px);
        -webkit-backdrop-filter: blur(4px);
        opacity: 0;
        pointer-events: none;
        transition: opacity 180ms ease;
    }

    body.kt-modern-ui #loader.visible {
        opacity: 1;
        pointer-events: auto;
    }

    body.kt-modern-ui #loader .spinner {
        width: 46px;
        height: 46px;
        border: 4px solid rgba(148, 163, 184, 0.35);
        border-top-color: var(--modern-accent-1);
        border-right-color: var(--modern-accent-2);
        border-radius: 50%;
        animation: ktSpin 0.9s linear infinite;
    }

    @keyframes ktSpin {
        to {
            transform: rotate(360deg);
        }
    }

    body.kt-modern-ui.kt-preset-minimal {
        --modern-shadow-soft: 0 8px 20px rgba(30, 41, 59, 0.14);
    }

    body.kt-modern-ui.kt-preset-corporate {
        --modern-shadow-soft: 0 10px 24px rgba(30, 64, 175, 0.2);
    }

    body.kt-modern-ui.kt-preset-neon .inf-node,
    body.kt-modern-ui.kt-preset-neon .action-card,
    body.kt-modern-ui.kt-preset-neon .stat-card {
        box-shadow: 0 0 24px rgba(124, 58, 237, 0.16);
    }

    body.kt-modern-ui.kt-reduced-motion :is(.bg-blob, #bg-canvas, .temp-gear-wheel, .temp-orbit-system) {
        animation: none !important;
        transition: none !important;
    }

    body.kt-modern-ui.kt-reduced-motion #bg-canvas {
        opacity: 0.16 !important;
    }
}

@layer app {
    @view-transition {
        navigation: auto;
    }

    :root {
        --modern-radius-2xl: 30px;
        --modern-text-tight: -0.02em;
    }

    body.kt-modern-ui {
        line-height: 1.45;
        letter-spacing: 0.01em;
        text-rendering: geometricPrecision;
        -webkit-font-smoothing: antialiased;
        background:
            radial-gradient(1000px 460px at -8% -10%, color-mix(in oklab, var(--modern-accent-1) 44%, transparent), transparent 62%),
            radial-gradient(900px 420px at 108% -6%, color-mix(in oklab, var(--modern-accent-2) 36%, transparent), transparent 58%),
            radial-gradient(720px 380px at 52% 118%, color-mix(in oklab, var(--modern-accent-3) 22%, transparent), transparent 68%),
            linear-gradient(140deg, var(--modern-bg-1), var(--modern-bg-2) 48%, var(--modern-bg-3));
    }

    body.kt-modern-ui::after {
        content: '';
        position: fixed;
        inset: 0;
        pointer-events: none;
        z-index: 0;
        background-image: linear-gradient(rgba(255, 255, 255, 0.024) 1px, transparent 1px), linear-gradient(90deg, rgba(255, 255, 255, 0.024) 1px, transparent 1px);
        background-size: 28px 28px;
        mask-image: radial-gradient(circle at center, black 36%, transparent 85%);
    }

    body.kt-modern-ui :is(main, header, footer) {
        position: relative;
        z-index: 1;
    }

    body.kt-modern-ui :is(.brand-text h1, h1, h2) {
        letter-spacing: var(--modern-text-tight);
    }

    body.kt-modern-ui h1 {
        font-size: clamp(1.45rem, 1.1rem + 1.2vw, 2rem);
    }

    body.kt-modern-ui h2 {
        font-size: clamp(1.2rem, 1rem + 0.8vw, 1.6rem);
    }

    body.kt-modern-ui :is(header, footer, .settings-section, .inf-center-circle, .side-main-wheel, .temp-wheel-content, .auth-logo-inner, .dashboard-container, .card-box, .stat-card, .action-card, .glass, .glass-panel, .glass-card, .bento-card) {
        border: 1px solid color-mix(in oklab, var(--text-primary) 18%, transparent) !important;
        background: linear-gradient(155deg, color-mix(in oklab, var(--card-bg) 84%, transparent), color-mix(in oklab, var(--card-bg) 65%, transparent)) !important;
        box-shadow: 0 12px 32px rgba(2, 6, 23, 0.28), inset 0 1px 0 rgba(255, 255, 255, 0.08);
        backdrop-filter: blur(22px) saturate(170%) !important;
        -webkit-backdrop-filter: blur(22px) saturate(170%) !important;
    }

    body.kt-modern-ui header {
        border-radius: 0 0 var(--modern-radius-2xl) var(--modern-radius-2xl);
    }

    body.kt-modern-ui main {
        border-radius: var(--modern-radius-2xl) !important;
        box-shadow: 0 18px 44px rgba(15, 23, 42, 0.22);
    }

    body.kt-modern-ui .nav-btn,
    body.kt-modern-ui .nav-link {
        background: linear-gradient(130deg, color-mix(in oklab, var(--modern-accent-1) 30%, transparent), color-mix(in oklab, var(--modern-accent-2) 30%, transparent)) !important;
        box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.24), 0 10px 20px rgba(6, 182, 212, 0.2);
    }

    body.kt-modern-ui .nav-btn:hover,
    body.kt-modern-ui .nav-link:hover {
        transform: translateY(-1px);
        filter: saturate(1.1);
    }

    body.kt-modern-ui :is(.inf-node, .side-node-row, .temp-icon-node, .action-card, .stat-card, .card-box, .notice-card, .settings-section) {
        border-radius: 18px !important;
        background: linear-gradient(160deg, color-mix(in oklab, var(--modern-accent-1) 14%, var(--card-bg)), color-mix(in oklab, var(--modern-accent-2) 9%, var(--card-bg))) !important;
    }

    body.kt-modern-ui :is(.inf-node:hover, .side-node-row:hover, .temp-icon-node:hover, .action-card:hover, .stat-card:hover, .card-box:hover, .settings-section:hover) {
        transform: translateY(-2px) scale(1.012);
        box-shadow: 0 14px 28px color-mix(in oklab, var(--modern-accent-2) 24%, transparent);
    }

    body.kt-modern-ui.kt-preset-minimal {
        --modern-accent-1: #334155;
        --modern-accent-2: #64748b;
        --modern-accent-3: #94a3b8;
    }

    body.kt-modern-ui.kt-preset-corporate {
        --modern-accent-1: #0f4c81;
        --modern-accent-2: #0369a1;
        --modern-accent-3: #0e7490;
    }

    body.kt-modern-ui.kt-preset-neon {
        --modern-accent-1: #8b5cf6;
        --modern-accent-2: #22d3ee;
        --modern-accent-3: #34d399;
    }

    body.kt-modern-ui.kt-reduced-motion::after {
        display: none;
    }
}

@layer reset, tokens, app, temp;

@layer reset {
    :root {
        --modern-bg-1: #060818;
        --modern-bg-2: #111a3c;
        --modern-bg-3: #132d4d;
        --modern-accent-1: #7c3aed;
        --modern-accent-2: #06b6d4;
        --modern-accent-3: #22c55e;
        --modern-danger: #ef4444;
        --modern-warning: #f59e0b;
        --modern-radius-xl: 24px;
        --modern-radius-lg: 16px;
        --modern-radius-md: 12px;
        --modern-shadow: 0 12px 35px rgba(2, 6, 23, 0.45);
        --modern-shadow-soft: 0 8px 24px rgba(15, 23, 42, 0.22);
    }

    body.kt-modern-ui {
        position: relative;
        background:
            radial-gradient(1000px 500px at 8% -5%, rgba(124, 58, 237, 0.35), transparent 60%),
            radial-gradient(900px 440px at 92% 5%, rgba(6, 182, 212, 0.28), transparent 58%),
            linear-gradient(145deg, var(--modern-bg-1), var(--modern-bg-2) 44%, var(--modern-bg-3));
        background-attachment: fixed;
    }

    body.kt-modern-ui.light-mode {
        --modern-bg-1: #eef4ff;
        --modern-bg-2: #dbeafe;
        --modern-bg-3: #f8fafc;
        --modern-shadow: 0 12px 30px rgba(30, 41, 59, 0.16);
        --modern-shadow-soft: 0 8px 22px rgba(15, 23, 42, 0.12);
    }

    @media (prefers-reduced-motion: reduce) {
        * {
            animation-duration: 0.001ms !important;
            animation-iteration-count: 1 !important;
            transition-duration: 0.001ms !important;
        }
    }
}

@layer app {
    body.kt-modern-ui {
        --ui-gap: clamp(0.75rem, 0.55rem + 0.9vw, 1.25rem);
        --ui-surface-1: color-mix(in oklab, var(--card-bg) 90%, transparent);
        --ui-surface-2: color-mix(in oklab, var(--card-bg) 72%, transparent);
        --ui-glow: color-mix(in oklab, var(--modern-accent-2) 28%, transparent);
        --ui-border-strong: color-mix(in oklab, var(--text-primary) 24%, transparent);
    }

    body.kt-modern-ui main {
        display: grid;
        gap: var(--ui-gap);
    }

    body.kt-modern-ui :is(header, footer, .glass, .glass-panel, .glass-card, .bento-card, .settings-section, .card-box, .action-card, .stat-card, .inf-node, .side-node-row, .temp-icon-node) {
        position: relative;
        isolation: isolate;
        border: 1px solid var(--ui-border-strong) !important;
        background: linear-gradient(160deg, var(--ui-surface-1), var(--ui-surface-2)) !important;
        box-shadow: 0 20px 45px rgba(2, 6, 23, 0.22), inset 0 1px 0 rgba(255, 255, 255, 0.1);
        overflow: clip;
    }

    body.kt-modern-ui :is(.glass, .glass-panel, .glass-card, .bento-card, .settings-section, .card-box, .action-card, .stat-card, .inf-node, .side-node-row, .temp-icon-node)::before {
        content: '';
        position: absolute;
        inset: -40% auto auto -20%;
        width: 120%;
        height: 60%;
        background: linear-gradient(100deg, rgba(255, 255, 255, 0.14), rgba(255, 255, 255, 0));
        transform: rotate(-6deg);
        pointer-events: none;
        z-index: 0;
    }

    body.kt-modern-ui :is(.glass, .glass-panel, .glass-card, .bento-card, .settings-section, .card-box, .action-card, .stat-card, .inf-node, .side-node-row, .temp-icon-node) > * {
        position: relative;
        z-index: 1;
    }

    body.kt-modern-ui :is(.inf-node:hover, .side-node-row:hover, .temp-icon-node:hover, .action-card:hover, .stat-card:hover, .card-box:hover, .settings-section:hover, .glass:hover, .glass-panel:hover, .glass-card:hover, .bento-card:hover) {
        border-color: var(--card-hover-border) !important;
        box-shadow: 0 18px 38px rgba(2, 6, 23, 0.28), 0 0 0 1px var(--ui-glow);
        transform: translateY(-3px) scale(1.012);
    }

    body.kt-modern-ui :is(.nav-btn, .nav-link) {
        background: linear-gradient(145deg, color-mix(in oklab, var(--modern-accent-1) 36%, transparent), color-mix(in oklab, var(--modern-accent-2) 42%, transparent)) !important;
        border: 1px solid color-mix(in oklab, var(--modern-accent-2) 38%, var(--card-border)) !important;
        box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.28), 0 12px 20px rgba(2, 132, 199, 0.24);
    }

    body.kt-modern-ui :is(.nav-btn, .nav-link):hover {
        transform: translateY(-1px) scale(1.03);
    }

    body.kt-modern-ui :is(.brand-text h1, h1, h2, h3) {
        text-wrap: balance;
    }

    body.kt-modern-ui :is(.setting-item, .card-box, .action-card, .stat-card, .inf-node, .side-node-row, .temp-icon-node) {
        border-radius: clamp(14px, 1.2vw, 20px) !important;
    }

    body.kt-modern-ui :is(.inf-center-circle, .side-main-wheel, .temp-wheel-content) {
        border: 1px solid color-mix(in oklab, var(--modern-accent-2) 26%, var(--card-border)) !important;
        background: radial-gradient(circle at 18% 12%, color-mix(in oklab, var(--modern-accent-2) 18%, transparent), transparent 62%), linear-gradient(160deg, var(--ui-surface-1), var(--ui-surface-2)) !important;
    }

    body.kt-modern-ui.kt-preset-minimal {
        --ui-glow: rgba(148, 163, 184, 0.2);
    }

    body.kt-modern-ui.kt-preset-corporate {
        --ui-glow: rgba(14, 116, 144, 0.26);
    }

    body.kt-modern-ui.kt-reduced-motion :is(.glass, .glass-panel, .glass-card, .bento-card, .settings-section, .card-box, .action-card, .stat-card, .inf-node, .side-node-row, .temp-icon-node) {
        transform: none !important;
        box-shadow: var(--modern-shadow-soft) !important;
    }
}

@layer tokens {
    body.kt-modern-ui {
        --card-bg: color-mix(in oklab, var(--surface) 74%, transparent);
        --card-border: color-mix(in oklab, var(--text-primary) 16%, transparent);
        --card-hover-border: color-mix(in oklab, var(--modern-accent-2) 38%, var(--text-primary) 10%);
    }

    @supports not (color: color-mix(in oklab, red, blue)) {
        body.kt-modern-ui {
            --card-bg: rgba(15, 23, 42, 0.72);
            --card-border: rgba(148, 163, 184, 0.32);
            --card-hover-border: rgba(6, 182, 212, 0.48);
        }

        body.kt-modern-ui.light-mode {
            --card-bg: rgba(255, 255, 255, 0.88);
            --card-border: rgba(15, 23, 42, 0.18);
            --card-hover-border: rgba(14, 165, 233, 0.42);
        }
    }
}

@layer app {
    body.kt-modern-ui .skip-link {
        position: fixed;
        left: 14px;
        top: 10px;
        z-index: 10001;
        transform: translateY(-180%);
        padding: 0.55rem 0.8rem;
        border-radius: 10px;
        border: 1px solid var(--card-border);
        background: rgba(2, 6, 23, 0.94);
        color: #f8fafc;
        text-decoration: none;
        font-weight: 700;
        transition: transform 0.2s ease;
    }

    body.kt-modern-ui .skip-link:focus-visible {
        transform: translateY(0);
    }

    body.kt-modern-ui :is(header, footer, .settings-section, .inf-center-circle, .side-main-wheel, .temp-wheel-content, .auth-logo-inner, .dashboard-container, .card-box, .stat-card, .action-card) {
        border: 1px solid var(--card-border) !important;
        background: var(--card-bg) !important;
        backdrop-filter: blur(20px) saturate(160%);
        -webkit-backdrop-filter: blur(20px) saturate(160%);
        box-shadow: var(--modern-shadow-soft);
    }

    body.kt-modern-ui header {
        border-radius: 0 0 var(--modern-radius-lg) var(--modern-radius-lg);
        margin: 0.35rem auto 0;
        width: min(1200px, 94%);
        position: sticky;
        top: max(0.2rem, env(safe-area-inset-top));
    }

    body.kt-modern-ui footer {
        width: min(1200px, 92%);
        margin: 1rem auto 1.25rem;
        border-radius: var(--modern-radius-md);
    }

    body.kt-modern-ui .nav-btn,
    body.kt-modern-ui .nav-link {
        border-radius: 999px !important;
        border-color: var(--card-border) !important;
        background: linear-gradient(135deg, rgba(124, 58, 237, 0.18), rgba(6, 182, 212, 0.18)) !important;
        color: var(--text-primary) !important;
        box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.04);
    }

    body.kt-modern-ui .brand-text h1 {
        background: linear-gradient(120deg, #ffffff 0%, #67e8f9 45%, #c4b5fd 100%) !important;
        -webkit-background-clip: text;
        -webkit-text-fill-color: transparent;
    }

    body.kt-modern-ui.light-mode .brand-text h1 {
        background: linear-gradient(120deg, #0f172a 0%, #0369a1 45%, #6d28d9 100%) !important;
        -webkit-background-clip: text;
        -webkit-text-fill-color: transparent;
    }

    body.kt-modern-ui #app-content main,
    body.kt-modern-ui main.infographic-wrapper,
    body.kt-modern-ui main {
        width: min(1240px, 96%);
        margin: 0.7rem auto 0;
        border-radius: var(--modern-radius-xl);
        padding: clamp(1rem, 2vw, 1.6rem) !important;
        background: linear-gradient(150deg, rgba(15, 23, 42, 0.48), rgba(15, 23, 42, 0.22));
        border: 1px solid var(--card-border);
    }

    body.kt-modern-ui.light-mode #app-content main,
    body.kt-modern-ui.light-mode main.infographic-wrapper,
    body.kt-modern-ui.light-mode main {
        background: linear-gradient(145deg, rgba(255, 255, 255, 0.72), rgba(241, 245, 249, 0.66));
    }

    body.kt-modern-ui .inf-center-circle,
    body.kt-modern-ui .side-main-wheel,
    body.kt-modern-ui .temp-wheel-content {
        border-radius: 28px !important;
        box-shadow: var(--modern-shadow);
    }

    body.kt-modern-ui .inf-node,
    body.kt-modern-ui .side-node-row,
    body.kt-modern-ui .temp-icon-node,
    body.kt-modern-ui .settings-section,
    body.kt-modern-ui .setting-item,
    body.kt-modern-ui .action-card,
    body.kt-modern-ui .stat-card,
    body.kt-modern-ui .card-box,
    body.kt-modern-ui .notice-card,
    body.kt-modern-ui .pin-dot {
        transition: transform 0.22s ease, box-shadow 0.22s ease, border-color 0.22s ease;
    }

    body.kt-modern-ui .inf-node,
    body.kt-modern-ui .side-node-row,
    body.kt-modern-ui .temp-icon-node,
    body.kt-modern-ui .action-card,
    body.kt-modern-ui .stat-card {
        border: 1px solid var(--card-border) !important;
        border-radius: var(--modern-radius-lg) !important;
        background: linear-gradient(160deg, rgba(124, 58, 237, 0.14), rgba(6, 182, 212, 0.08)) !important;
    }

    body.kt-modern-ui .inf-node:hover,
    body.kt-modern-ui .side-node-row:hover,
    body.kt-modern-ui .temp-icon-node:hover,
    body.kt-modern-ui .action-card:hover,
    body.kt-modern-ui .stat-card:hover,
    body.kt-modern-ui .settings-section:hover {
        transform: translateY(-2px) scale(1.01);
        border-color: var(--card-hover-border) !important;
        box-shadow: 0 12px 30px rgba(6, 182, 212, 0.2);
    }

    body.kt-modern-ui .pin-dot.filled {
        border-color: var(--modern-accent-2) !important;
        box-shadow: 0 0 0 5px rgba(6, 182, 212, 0.2), 0 0 18px rgba(6, 182, 212, 0.6) !important;
    }

    body.kt-modern-ui .pin-dot.error {
        border-color: var(--modern-danger) !important;
    }

    body.kt-modern-ui .settings-section {
        border-radius: var(--modern-radius-lg) !important;
    }

    body.kt-modern-ui .setting-item {
        border-bottom-color: color-mix(in oklab, var(--text-primary) 12%, transparent) !important;
    }

    body.kt-modern-ui .toggle-switch .slider {
        border: 1px solid var(--card-border);
        background: rgba(148, 163, 184, 0.32);
    }

    body.kt-modern-ui .toggle-switch input:checked + .slider {
        background: linear-gradient(120deg, var(--modern-accent-1), var(--modern-accent-2));
    }

    body.kt-modern-ui #change-pin-btn,
    body.kt-modern-ui #save-pin-btn,
    body.kt-modern-ui #clear-data-btn {
        border: 1px solid transparent;
        background: linear-gradient(120deg, var(--modern-accent-1), var(--modern-accent-2));
        box-shadow: 0 8px 18px rgba(6, 182, 212, 0.24);
    }

    body.kt-modern-ui #loader .spinner {
        border-right-color: var(--modern-accent-2) !important;
        border-top-color: var(--modern-accent-1) !important;
    }

    @container (min-width: 900px) {
        body.kt-modern-ui .infographic-container {
            gap: clamp(16px, 2vw, 38px);
        }
    }
}

@layer temp {
    body.kt-modern-ui .dashboard-container {
        border-radius: 28px;
        overflow: clip;
        min-height: min(780px, 95dvh);
    }

    body.kt-modern-ui .sidebar {
        background: linear-gradient(170deg, rgba(12, 74, 110, 0.94), rgba(88, 28, 135, 0.94));
        border-top-right-radius: 28px;
    }

    body.kt-modern-ui .nav-item.active {
        border-radius: 999px 0 0 999px;
        margin-left: 14px;
        box-shadow: 0 8px 20px rgba(15, 23, 42, 0.2);
    }

    body.kt-modern-ui .main-content {
        background: transparent;
        gap: 16px;
    }

    body.kt-modern-ui .logo {
        letter-spacing: 0.04em;
        text-transform: uppercase;
    }

    body.kt-modern-ui .calendar-days .day-cell,
    body.kt-modern-ui .calendar-months span {
        border-radius: 10px;
    }
}

@layer app {
    body.kt-modern-ui {
        --control-size: 42px;
        --control-radius: 999px;
        --focus-ring: 0 0 0 3px rgba(6, 182, 212, 0.34);
    }

    body.kt-modern-ui :is(.nav-btn, .nav-link) {
        width: var(--control-size) !important;
        height: var(--control-size) !important;
        border-radius: var(--control-radius) !important;
    }

    body.kt-modern-ui :is(button, [role='button'], a, input, select, textarea):focus-visible {
        outline: none;
        box-shadow: var(--focus-ring) !important;
    }

    body.kt-modern-ui :is(.inf-node, .side-node-row, .temp-icon-node, .action-card, .stat-card, .card-box, .notice-card).kt-press {
        transform: scale(0.98) !important;
    }

    body.kt-modern-ui.kt-page-enter {
        opacity: 0.001;
        transform: translateY(8px);
    }

    body.kt-modern-ui.kt-page-enter.kt-page-enter-active {
        opacity: 1;
        transform: translateY(0);
        transition: opacity 260ms ease, transform 260ms ease;
    }

    body.kt-modern-ui #loader {
        position: fixed;
        inset: 0;
        z-index: 9999;
        display: grid;
        place-items: center;
        background: rgba(2, 6, 23, 0.42);
        backdrop-filter: blur(4px);
        -webkit-backdrop-filter: blur(4px);
        opacity: 0;
        pointer-events: none;
        transition: opacity 180ms ease;
    }

    body.kt-modern-ui #loader.visible {
        opacity: 1;
        pointer-events: auto;
    }

    body.kt-modern-ui #loader .spinner {
        width: 46px;
        height: 46px;
        border: 4px solid rgba(148, 163, 184, 0.35);
        border-top-color: var(--modern-accent-1);
        border-right-color: var(--modern-accent-2);
        border-radius: 50%;
        animation: ktSpin 0.9s linear infinite;
    }

    @keyframes ktSpin {
        to {
            transform: rotate(360deg);
        }
    }

    body.kt-modern-ui.kt-preset-minimal {
        --modern-shadow-soft: 0 8px 20px rgba(30, 41, 59, 0.14);
    }

    body.kt-modern-ui.kt-preset-corporate {
        --modern-shadow-soft: 0 10px 24px rgba(30, 64, 175, 0.2);
    }

    body.kt-modern-ui.kt-preset-neon .inf-node,
    body.kt-modern-ui.kt-preset-neon .action-card,
    body.kt-modern-ui.kt-preset-neon .stat-card {
        box-shadow: 0 0 24px rgba(124, 58, 237, 0.16);
    }

    body.kt-modern-ui.kt-reduced-motion :is(.bg-blob, #bg-canvas, .temp-gear-wheel, .temp-orbit-system) {
        animation: none !important;
        transition: none !important;
    }

    body.kt-modern-ui.kt-reduced-motion #bg-canvas {
        opacity: 0.16 !important;
    }
}

@layer app {
    @view-transition {
        navigation: auto;
    }

    :root {
        --modern-radius-2xl: 30px;
        --modern-text-tight: -0.02em;
    }

    body.kt-modern-ui {
        line-height: 1.45;
        letter-spacing: 0.01em;
        text-rendering: geometricPrecision;
        -webkit-font-smoothing: antialiased;
        background:
            radial-gradient(1000px 460px at -8% -10%, color-mix(in oklab, var(--modern-accent-1) 44%, transparent), transparent 62%),
            radial-gradient(900px 420px at 108% -6%, color-mix(in oklab, var(--modern-accent-2) 36%, transparent), transparent 58%),
            radial-gradient(720px 380px at 52% 118%, color-mix(in oklab, var(--modern-accent-3) 22%, transparent), transparent 68%),
            linear-gradient(140deg, var(--modern-bg-1), var(--modern-bg-2) 48%, var(--modern-bg-3));
    }

    body.kt-modern-ui::after {
        content: '';
        position: fixed;
        inset: 0;
        pointer-events: none;
        z-index: 0;
        background-image: linear-gradient(rgba(255, 255, 255, 0.024) 1px, transparent 1px), linear-gradient(90deg, rgba(255, 255, 255, 0.024) 1px, transparent 1px);
        background-size: 28px 28px;
        mask-image: radial-gradient(circle at center, black 36%, transparent 85%);
    }

    body.kt-modern-ui :is(main, header, footer) {
        position: relative;
        z-index: 1;
    }

    body.kt-modern-ui :is(.brand-text h1, h1, h2) {
        letter-spacing: var(--modern-text-tight);
    }

    body.kt-modern-ui h1 {
        font-size: clamp(1.45rem, 1.1rem + 1.2vw, 2rem);
    }

    body.kt-modern-ui h2 {
        font-size: clamp(1.2rem, 1rem + 0.8vw, 1.6rem);
    }

    body.kt-modern-ui :is(header, footer, .settings-section, .inf-center-circle, .side-main-wheel, .temp-wheel-content, .auth-logo-inner, .dashboard-container, .card-box, .stat-card, .action-card, .glass, .glass-panel, .glass-card, .bento-card) {
        border: 1px solid color-mix(in oklab, var(--text-primary) 18%, transparent) !important;
        background: linear-gradient(155deg, color-mix(in oklab, var(--card-bg) 84%, transparent), color-mix(in oklab, var(--card-bg) 65%, transparent)) !important;
        box-shadow: 0 12px 32px rgba(2, 6, 23, 0.28), inset 0 1px 0 rgba(255, 255, 255, 0.08);
        backdrop-filter: blur(22px) saturate(170%) !important;
        -webkit-backdrop-filter: blur(22px) saturate(170%) !important;
    }

    body.kt-modern-ui header {
        border-radius: 0 0 var(--modern-radius-2xl) var(--modern-radius-2xl);
    }

    body.kt-modern-ui main {
        border-radius: var(--modern-radius-2xl) !important;
        box-shadow: 0 18px 44px rgba(15, 23, 42, 0.22);
    }

    body.kt-modern-ui .nav-btn,
    body.kt-modern-ui .nav-link {
        background: linear-gradient(130deg, color-mix(in oklab, var(--modern-accent-1) 30%, transparent), color-mix(in oklab, var(--modern-accent-2) 30%, transparent)) !important;
        box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.24), 0 10px 20px rgba(6, 182, 212, 0.2);
    }

    body.kt-modern-ui .nav-btn:hover,
    body.kt-modern-ui .nav-link:hover {
        transform: translateY(-1px);
        filter: saturate(1.1);
    }

    body.kt-modern-ui :is(.inf-node, .side-node-row, .temp-icon-node, .action-card, .stat-card, .card-box, .notice-card, .settings-section) {
        border-radius: 18px !important;
        background: linear-gradient(160deg, color-mix(in oklab, var(--modern-accent-1) 14%, var(--card-bg)), color-mix(in oklab, var(--modern-accent-2) 9%, var(--card-bg))) !important;
    }

    body.kt-modern-ui :is(.inf-node:hover, .side-node-row:hover, .temp-icon-node:hover, .action-card:hover, .stat-card:hover, .card-box:hover, .settings-section:hover) {
        transform: translateY(-2px) scale(1.012);
        box-shadow: 0 14px 28px color-mix(in oklab, var(--modern-accent-2) 24%, transparent);
    }

    body.kt-modern-ui.kt-preset-minimal {
        --modern-accent-1: #334155;
        --modern-accent-2: #64748b;
        --modern-accent-3: #94a3b8;
    }

    body.kt-modern-ui.kt-preset-corporate {
        --modern-accent-1: #0f4c81;
        --modern-accent-2: #0369a1;
        --modern-accent-3: #0e7490;
    }

    body.kt-modern-ui.kt-preset-neon {
        --modern-accent-1: #8b5cf6;
        --modern-accent-2: #22d3ee;
        --modern-accent-3: #34d399;
    }

    body.kt-modern-ui.kt-reduced-motion::after {
        display: none;
    }
}
